var a=[{title:`Misura l’impronta`,text:`Annota lunghezza e larghezza del pavimento libero, che di solito è più piccolo della stanza stessa. Un curl in piedi richiede abbastanza poco spazio, mentre un affondo camminato o un esercizio a terra possono richiedere spazio per allungare braccia e gambe. Lascia spazio in più attorno ai pesi in movimento e pensa a come l’esercizio inizia e finisce.`},{title:`Pensa in tre dimensioni`,text:`Uno squat o un rematore in piedi richiede spazio ai lati per i gomiti e per l’attrezzatura. Un push-up o un dead bug richiedono spazio sul pavimento lungo quanto il tuo corpo. Uno swing con la kettlebell richiede spazio aperto davanti, dietro e attorno alla kettlebell, e le distensioni sopra la testa o i salti richiedono spazio in verticale.`},{title:`Ostacoli nascosti`,text:`Fai attenzione a tavolini bassi, luci sospese, spigoli, stufe, animali domestici, cavi, tappeti e porte che si aprono nella tua area. Controlla che il pavimento sia ancora antiscivolo una volta steso il tappetino. Se riesci a malapena a completare una ripetizione senza toccare i mobili, lo spazio è troppo stretto per un allenamento completo.`},{title:`Un piano per gli spazi piccoli`,text:`In uno spazio stretto, fai split squat da fermo al posto degli affondi camminati, e lavoro per la parte alta del corpo da seduto o a terra al posto di grandi movimenti da un lato all’altro. Se la stanza è troppo piccola per i carry con carico, fai esercizi anti-flessione laterale sul posto. Mantieni lo schema di movimento e lascia cambiare l’esercizio specifico.`},{title:`Usare TrainUp`,text:`Inserisci in Profilo le dimensioni del pavimento e l’altezza del soffitto. Il piano sceglie quindi solo esercizi il cui movimento, attrezzatura compresa, sta in quello spazio.`}];var o=[{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: sicurezza e tecnica dell’allenamento coi pesi`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};